#!/usr/bin/env python3
import io
import json
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

TEMPLATE_PATH = "/root/event_announcement_template.hwpx"
DATA_PATH = "/root/event_data.json"
OUTPUT_PATH = "/root/event_announcement_ready.hwpx"

PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def load_event_data(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("event_data.json must contain a JSON object")
    # stringify all values to be safe
    return {str(k): "" if v is None else str(v) for k, v in data.items()}


def collect_namespaces(xml_bytes: bytes) -> dict:
    """Collect prefix->URI mappings without building a modified tree."""
    ns = {}
    for event, item in ET.iterparse(io.BytesIO(xml_bytes), events=("start-ns",)):
        prefix, uri = item
        # ElementTree uses '' for default namespace
        if prefix in ns and ns[prefix] == uri:
            continue
        ns[prefix] = uri
    return ns


def register_namespaces(ns: dict) -> None:
    # Register in a stable order: default namespace first (''), then others sorted.
    if "" in ns:
        ET.register_namespace("", ns[""])
    for prefix in sorted([p for p in ns.keys() if p != ""]):
        ET.register_namespace(prefix, ns[prefix])


def replace_placeholders_in_text(text: str, data: dict) -> str:
    if not text:
        return text
    out = text
    for k, v in data.items():
        out = out.replace("{{" + k + "}}", v)
    return out


def has_any_placeholder(text: str) -> bool:
    return bool(text) and ("{{" in text and "}}" in text)


def local_name(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def find_children_by_local(parent, lname: str):
    for ch in list(parent):
        if local_name(ch.tag) == lname:
            yield ch


def remove_layout_cache_from_paragraph(p_elem, parent_map) -> int:
    """Remove hp:lineSegArray / hp:linesegarray elements inside this paragraph."""
    removed = 0
    targets = []
    for elem in p_elem.iter():
        ln = local_name(elem.tag)
        if ln in ("lineSegArray", "linesegarray"):
            targets.append(elem)
    for elem in targets:
        par = parent_map.get(elem)
        if par is not None:
            par.remove(elem)
            removed += 1
    return removed


def normalize_runs_and_replace(root, data: dict) -> tuple[bool, int]:
    """Normalize split placeholders within <hp:run> by merging <hp:t>.

    Returns (any_modified, modified_paragraph_count)
    """
    # Build parent map once so we can remove lineSeg arrays later.
    parent_map = {}
    for parent in root.iter():
        for child in list(parent):
            parent_map[child] = parent

    any_modified = False
    modified_paras = 0

    # HWPX paragraph elements are typically hp:p
    for p in root.iter():
        if local_name(p.tag) != "p":
            continue

        paragraph_modified = False

        # Runs are children; but traverse all descendants to be safe.
        for run in p.iter():
            if local_name(run.tag) != "run":
                continue

            t_elems = [e for e in list(run) if local_name(e.tag) == "t"]
            if not t_elems:
                continue

            combined = "".join([(t.text or "") for t in t_elems])
            if not has_any_placeholder(combined):
                continue

            replaced = replace_placeholders_in_text(combined, data)

            # Only normalize (collapse to a single <hp:t>) when we saw placeholders
            # in the combined text (split or not). This matches the requirement.
            first = t_elems[0]
            if (first.text or "") != replaced or len(t_elems) != 1:
                first.text = replaced
                for extra in t_elems[1:]:
                    run.remove(extra)
                paragraph_modified = True

        if paragraph_modified:
            any_modified = True
            modified_paras += 1
            remove_layout_cache_from_paragraph(p, parent_map)

    return any_modified, modified_paras


def finalize_string_level_replacement(xml_text: str, data: dict) -> str:
    out = xml_text
    for k, v in data.items():
        out = out.replace("{{" + k + "}}", v)
    return out


def assert_no_placeholders_left(xml_text: str, file_name: str) -> None:
    if "{{" in xml_text:
        # show a small sample of remaining placeholders to help debugging
        samples = sorted(set(PLACEHOLDER_RE.findall(xml_text)))
        raise RuntimeError(
            f"Unreplaced placeholders remain in {file_name}: "
            + (", ".join(samples[:20]) if samples else "(unable to extract keys)")
        )


def main() -> int:
    data = load_event_data(DATA_PATH)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin, zipfile.ZipFile(
        OUTPUT_PATH, "w", compression=zipfile.ZIP_DEFLATED
    ) as zout:
        for info in zin.infolist():
            raw = zin.read(info.filename)

            if not info.filename.lower().endswith(".xml"):
                # Preserve non-XML files as-is
                zout.writestr(info, raw)
                continue

            # Parse XML with namespace preservation
            ns = collect_namespaces(raw)
            register_namespaces(ns)

            # Print namespace info for the main section XML (once)
            if info.filename == "Contents/section0.xml":
                try:
                    tmp_root = ET.fromstring(raw)
                    print("[ns-debug] root.tag:", tmp_root.tag)
                    print("[ns-debug] namespaces:")
                    for k in sorted(ns.keys()):
                        label = k if k != "" else "(default)"
                        print(f"  - {label}: {ns[k]}")
                except Exception as e:
                    print("[ns-debug] failed to parse for namespace debug:", e, file=sys.stderr)

            root = ET.fromstring(raw)

            any_modified, modified_para_count = normalize_runs_and_replace(root, data)

            # Serialize
            xml_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
            xml_text = xml_bytes.decode("utf-8")

            # Second pass: catch any remaining placeholders not split across <hp:t>
            xml_text2 = finalize_string_level_replacement(xml_text, data)

            # If we modified paragraphs structurally, we already removed lineSegArray/linesegarray
            # elements from those paragraphs. We intentionally do NOT remove layout caches from
            # unmodified paragraphs.

            assert_no_placeholders_left(xml_text2, info.filename)

            if any_modified:
                print(
                    f"[xml] {info.filename}: modified_paragraphs={modified_para_count}"
                )

            zout.writestr(info, xml_text2.encode("utf-8"))

    print(f"Wrote: {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

