        out = out.replace("{{" + k + "}}", v)
    return out


def assert_no_placeholders_left(xml_text: str, file_name: str) -> None:
    if "{{" in xml_text:
        # show a small sample of remaining placeholders to help debugging
        samples = sorted(set(PLACEHOLDER_RE.findall(xml_text)))
        raise RuntimeError(
            f"Unreplaced placeholders remain in {file_name}: "
            + (", ".join(samples[:20]) if samples else "(unable to extract keys)")
        )


def main() -> int:
    data = load_event_data(DATA_PATH)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin, zipfile.ZipFile(
        OUTPUT_PATH, "w", compression=zipfile.ZIP_DEFLATED
    ) as zout:
        for info in zin.infolist():
            raw = zin.read(info.filename)

            if not info.filename.lower().endswith(".xml"):
                # Preserve non-XML files as-is
                zout.writestr(info, raw)
                continue

            # Parse XML with namespace preservation
            ns = collect_namespaces(raw)
            register_namespaces(ns)

            # Print namespace info for the main section XML (once)
            if info.filename == "Contents/section0.xml":
                try:
                    tmp_root = ET.fromstring(raw)
                    print("[ns-debug] root.tag:", tmp_root.tag)
                    print("[ns-debug] namespaces:")
                    for k in sorted(ns.keys()):
                        label = k if k != "" else "(default)"
                        print(f"  - {label}: {ns[k]}")
                except Exception as e:
                    print("[ns-debug] failed to parse for namespace debug:", e, file=sys.stderr)

            root = ET.fromstring(raw)

            any_modified, modified_para_count = normalize_runs_and_replace(root, data)

            # Serialize
            xml_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
            xml_text = xml_bytes.decode("utf-8")

            # Second pass: catch any remaining placeholders not split across <hp:t>
            xml_text2 = finalize_string_level_replacement(xml_text, data)

            # If we modified paragraphs structurally, we already removed lineSegArray/linesegarray
            # elements from those paragraphs. We intentionally do NOT remove layout caches from
            # unmodified paragraphs.

            assert_no_placeholders_left(xml_text2, info.filename)

            if any_modified:
                print(
                    f"[xml] {info.filename}: modified_paragraphs={modified_para_count}"
                )

            zout.writestr(info, xml_text2.encode("utf-8"))

    print(f"Wrote: {OUTPUT_PATH}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

